@import "tailwindcss";

@theme {
  --color-lava-cream: #FFF5E1;
  --color-molten-coral: #FF4D38;
  --color-jalapeno-teal: #00B8A0;
  --color-habanero-yellow: #FFD600;
  --color-ghost-purple: #7B2FBE;
  --color-smoke-black: #1A1209;
  --color-confetti-pink: #FF85A1;
  --color-sauce-green: #1D7A3A;

  --font-display: "Boogaloo", system-ui, sans-serif;
  --font-body: "Nunito", system-ui, sans-serif;
  --font-marker: "Permanent Marker", cursive;

  --animate-marquee: marquee 22s linear infinite;
  --animate-marquee-slow: marquee 60s linear infinite;
  --animate-float-y: float-y 4s ease-in-out infinite;
  --animate-float-y-slow: float-y 5s ease-in-out infinite;
  --animate-pulse-glow: pulse-glow 2.5s ease-in-out infinite;
  --animate-bob: bob 2s ease-in-out infinite;
  --animate-rotate-slow: rotate-slow 8s ease-in-out infinite;
  --animate-pattern-drift: pattern-drift 12s linear infinite;
  --animate-pin-pulse: pin-pulse 3.5s ease-in-out infinite;

  @keyframes marquee {
    from { transform: translateX(0); }
    to { transform: translateX(-50%); }
  }
  @keyframes float-y {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
  }
  @keyframes pulse-glow {
    0%, 100% { box-shadow: 0 0 0 0 rgba(255, 214, 0, 0.55), 5px 5px 0 0 #1A1209; }
    50% { box-shadow: 0 0 0 16px rgba(255, 214, 0, 0), 5px 5px 0 0 #1A1209; }
  }
  @keyframes bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(6px); }
  }
  @keyframes rotate-slow {
    0%, 100% { transform: rotate(-1deg); }
    50% { transform: rotate(2deg); }
  }
  @keyframes pattern-drift {
    from { background-position: 0 0; }
    to { background-position: 80px 80px; }
  }
  @keyframes pin-pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.08); }
  }
}

@layer base {
  html {
    scroll-behavior: smooth;
  }
  body {
    font-family: var(--font-body);
    background-color: var(--color-lava-cream);
    color: var(--color-smoke-black);
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }
  h1, h2, h3, h4 {
    font-family: var(--font-display);
    line-height: 1.05;
  }
}

@utility hardshadow {
  box-shadow: 5px 5px 0 0 #1A1209;
}
@utility hardshadow-sm {
  box-shadow: 3px 3px 0 0 #1A1209;
}
@utility hardshadow-lg {
  box-shadow: 8px 8px 0 0 #1A1209;
}

@utility text-stroke-black {
  -webkit-text-stroke: 3px #1A1209;
  paint-order: stroke fill;
}
@utility text-stroke-thin {
  -webkit-text-stroke: 2px #1A1209;
  paint-order: stroke fill;
}

.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s cubic-bezier(.22,.7,.18,1), transform 0.7s cubic-bezier(.22,.7,.18,1);
}
.reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}
.reveal-stagger > * {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.6s cubic-bezier(.22,.7,.18,1), transform 0.6s cubic-bezier(.22,.7,.18,1);
}
.reveal-stagger.is-visible > * {
  opacity: 1;
  transform: translateY(0);
}
.reveal-stagger.is-visible > *:nth-child(1) { transition-delay: 0ms; }
.reveal-stagger.is-visible > *:nth-child(2) { transition-delay: 120ms; }
.reveal-stagger.is-visible > *:nth-child(3) { transition-delay: 240ms; }
.reveal-stagger.is-visible > *:nth-child(4) { transition-delay: 360ms; }
.reveal-stagger.is-visible > *:nth-child(5) { transition-delay: 480ms; }
.reveal-stagger.is-visible > *:nth-child(6) { transition-delay: 600ms; }

.reveal-left {
  opacity: 0;
  transform: translateX(-40px);
  transition: opacity 0.7s cubic-bezier(.22,.7,.18,1), transform 0.7s cubic-bezier(.22,.7,.18,1);
}
.reveal-left.is-visible {
  opacity: 1;
  transform: translateX(0);
}
.reveal-right {
  opacity: 0;
  transform: translateX(40px);
  transition: opacity 0.7s cubic-bezier(.22,.7,.18,1), transform 0.7s cubic-bezier(.22,.7,.18,1);
}
.reveal-right.is-visible {
  opacity: 1;
  transform: translateX(0);
}

.year-slam {
  opacity: 0;
  transform: translateX(-160px);
}
.year-slam.is-visible {
  animation: year-slam 0.8s cubic-bezier(.18,.9,.32,1.3) forwards;
}
@keyframes year-slam {
  0% { opacity: 0; transform: translateX(-160px); }
  70% { opacity: 1; transform: translateX(10px); }
  100% { opacity: 1; transform: translateX(0); }
}

.bar-grow {
  width: 0;
  transition: width 1.2s cubic-bezier(.22,.7,.18,1);
}
.bar-grow.is-visible {
  width: 100%;
}

.flame-pop {
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.4);
  transition: opacity 0.3s, transform 0.4s cubic-bezier(.18,.9,.32,1.5);
}
.flame-pop.is-visible {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}

.hero-fade-up {
  opacity: 0;
  transform: translateY(40px);
  animation: hero-fade-up 0.9s cubic-bezier(.18,.9,.32,1.05) forwards;
}
@keyframes hero-fade-up {
  to { opacity: 1; transform: translateY(0); }
}

.hero-pop {
  opacity: 0;
  transform: scale(0.4);
  animation: hero-pop 0.6s cubic-bezier(.18,.9,.32,1.5) forwards;
}
@keyframes hero-pop {
  to { opacity: 1; transform: scale(1); }
}

.shape-drift {
  animation: shape-drift 10s ease-in-out infinite;
}
@keyframes shape-drift {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-12px) rotate(3deg); }
}

.confetti-float-1 { animation: float-y 3.2s ease-in-out infinite; }
.confetti-float-2 { animation: float-y 4.1s ease-in-out 0.4s infinite; }
.confetti-float-3 { animation: float-y 3.6s ease-in-out 0.8s infinite; }
.confetti-float-4 { animation: float-y 4.5s ease-in-out 1.2s infinite; }
.confetti-float-5 { animation: float-y 3.8s ease-in-out 1.6s infinite; }
.confetti-float-6 { animation: float-y 4.2s ease-in-out 2.0s infinite; }

.dani-letterform {
  opacity: 0;
  transform: translateX(60vw) rotate(7deg);
  transition: opacity 0.7s ease, transform 0.7s cubic-bezier(.22,.7,.18,1);
}
.dani-letterform.is-visible {
  opacity: 1;
  transform: translateX(0) rotate(7deg);
}

.squiggle-draw {
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.45s ease;
}
.squiggle-draw.is-visible {
  transform: scaleX(1);
}

.pattern-tile {
  background-repeat: repeat;
}

