const links = [
  { label: 'Home', href: '/index.html' },
  { label: 'Products', href: '/products.html' },
  { label: 'Our Story', href: '/story.html' },
  { label: 'Stockists', href: '/stockists.html' },
  { label: 'Contact', href: '/contact.html' },
];

export default function Nav(props) {
  const current = props.current || 'home';
  return (
    <header class="relative z-50 border-b-[3px] border-smoke-black bg-lava-cream">
      <div class="mx-auto flex max-w-7xl items-center justify-between px-6 py-4 lg:px-10">
        <a href="/index.html" class="flex items-center gap-3 group">
          <span class="relative inline-block">
            <svg width="44" height="44" viewBox="0 0 44 44" class="transition-transform group-hover:rotate-6">
              <circle cx="22" cy="22" r="20" fill="#FFD600" stroke="#1A1209" stroke-width="2.5" />
              <path d="M22 8 C26 12, 28 18, 28 24 C28 30, 25 34, 22 34 C19 34, 16 30, 16 24 C16 18, 18 12, 22 8 Z" fill="#FF4D38" stroke="#1A1209" stroke-width="2.5" stroke-linejoin="round" />
              <path d="M22 9 C23 7, 25 6, 26 7 C26 9, 24 10, 22 10 Z" fill="#1D7A3A" stroke="#1A1209" stroke-width="1.8" stroke-linejoin="round" />
            </svg>
          </span>
          <span class="font-display text-2xl tracking-tight text-smoke-black">Lava Mouth</span>
        </a>
        <nav class="hidden lg:flex items-center gap-1">
          {links.map((l) => (
            <a
              href={l.href}
              class={`relative font-display text-lg px-4 py-2 transition-colors ${l.label.toLowerCase().replace(/[^a-z]/g, '') === current || (current === 'home' && l.label === 'Home') ? 'text-molten-coral' : 'text-smoke-black hover:text-molten-coral'}`}
