          ))}
        </nav>
        <a href="/products.html" class="hidden lg:inline-flex items-center gap-2 bg-molten-coral text-lava-cream font-display text-base px-5 py-2.5 border-2 border-smoke-black rounded-md hardshadow-sm hover:-translate-y-0.5 hover:translate-x-0 transition-transform">
          Shop
          <span aria-hidden>→</span>
        </a>
        <a href="/products.html" class="lg:hidden bg-molten-coral text-lava-cream font-display text-base px-4 py-2 border-2 border-smoke-black rounded-md hardshadow-sm">Shop</a>
      </div>
    </header>
  );
}

