    const parsed = new URL(href, "http://127.0.0.1:3000");
    if (parsed.origin !== "http://127.0.0.1:3000") return null;
    if (parsed.pathname === "/index.html") return "/";
    return parsed.pathname;
  } catch {
    return null;
  }
}

