import { onMount, onCleanup } from 'solid-js';

let observer;
const tracked = new Set();

function getObserver() {
  if (typeof window === 'undefined') return null;
  if (!observer) {
    observer = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            e.target.classList.add('is-visible');
            observer.unobserve(e.target);
            tracked.delete(e.target);
          }
        }
      },
      { threshold: 0.05, rootMargin: '0px 0px -2% 0px' }
    );

    // Safety net: any element still not revealed after 1800ms (e.g.
    // headless screenshot capture that does not scroll naturally) gets
    // revealed regardless. Interactive visitors still see the staggered
    // animations for sections they reach within that window.
    window.addEventListener('load', () => {
      setTimeout(() => {
        tracked.forEach((el) => el.classList.add('is-visible'));
      }, 1800);
    });
    // Backup if load already fired
    setTimeout(() => {
      tracked.forEach((el) => el.classList.add('is-visible'));
    }, 2200);
  }
  return observer;
}

export function useReveal() {
  return (el) => {
    if (!el) return;
    onMount(() => {
      const obs = getObserver();
      if (obs) {
        obs.observe(el);
        tracked.add(el);
      }
    });
    onCleanup(() => {
      const obs = getObserver();
      if (obs) {
        obs.unobserve(el);
        tracked.delete(el);
      }
    });
  };
}

