import { createSignal, onMount, onCleanup } from 'solid-js';

export default function StatCounter(props) {
  const target = props.value;
  const [display, setDisplay] = createSignal(props.startAt ?? 0);
  const [bouncing, setBouncing] = createSignal(false);
  let el;
  let started = false;

  const start = () => {
    if (started) return;
    started = true;
    const t0 = performance.now();
    const dur = props.duration || 1100;
    const delay = props.delay || 0;
    const tick = (now) => {
      const elapsed = now - t0 - delay;
      if (elapsed < 0) {
        requestAnimationFrame(tick);
        return;
      }
      const t = Math.min(elapsed / dur, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      setDisplay(Math.floor(target * eased));
      if (t < 1) {
        requestAnimationFrame(tick);
      } else {
        setDisplay(target);
        setBouncing(true);
        setTimeout(() => setBouncing(false), 400);
      }
    };
    requestAnimationFrame(tick);
  };

  onMount(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          observer.disconnect();
          start();
        }
      },
      { threshold: 0.2 }
    );
    observer.observe(el);
    // Safety: ensure counter completes even without visible scroll.
    const fallback = setTimeout(start, 2500);
    onCleanup(() => {
      observer.disconnect();
      clearTimeout(fallback);
    });
  });

  const format = (n) => {
    if (props.format === 'commas') return n.toLocaleString();
    return String(n);
  };

  return (
    <span
      ref={el}
      class={`inline-block transition-transform duration-300 ${bouncing() ? 'scale-110' : 'scale-100'}`}
    >
      {format(display())}{props.suffix || ''}
    </span>
  );
}

