import { render } from 'solid-js/web';
import { createSignal, onMount } from 'solid-js';
import '../styles/tailwind.css';
import PageLayout from '../components/PageLayout.jsx';
import Marquee from '../components/Marquee.jsx';
import { useReveal } from '../components/Reveal.jsx';
import {
  Squiggle,
  Zigzag,
  Triangle,
  Dot,
  Starburst,
  Diamond,
  FlameIcon,
  MemphisPatternBg,
} from '../components/Illustrations.jsx';

function PageHeader() {
  const reveal = useReveal();
  // build a pattern data URI via inline SVG
  const patternSvg = encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140' viewBox='0 0 140 140'>
      <rect width='140' height='140' fill='%23FFF5E1' />
      <circle cx='20' cy='20' r='6' fill='%23FF85A1' />
      <circle cx='20' cy='20' r='2' fill='%231A1209' />
      <polyline points='44,8 54,28 64,8 74,28 84,8' stroke='%2300B8A0' stroke-width='4' fill='none' />
      <polygon points='112,10 128,38 96,38' fill='%23FFD600' stroke='%231A1209' stroke-width='2'/>
      <path d='M10 78 Q22 66 34 78 T58 78' stroke='%237B2FBE' stroke-width='4' fill='none' stroke-linecap='round'/>
      <path d='M76 86 C80 78,88 76,92 84 C88 90,80 90,76 86 Z' fill='%23FF4D38' stroke='%231A1209' stroke-width='2'/>
      <rect x='106' y='90' width='28' height='4' fill='%231A1209' />
      <circle cx='54' cy='126' r='8' fill='%23FFD600' stroke='%231A1209' stroke-width='2'/>
      <polygon points='128,128 138,138 118,138' fill='%23FF85A1' stroke='%231A1209' stroke-width='2'/>
    </svg>`
  ).replace(/'/g, '%27');

  return (
    <section
      id="products-section-1"
      data-section-type="page_header"
      class="relative overflow-hidden border-b-[6px] border-jalapeno-teal"
      style={{
        'background-image': `url("data:image/svg+xml;utf8,${patternSvg.replace(/%23/g, '%23')}")`,
        'background-color': '#FFF5E1',
        'background-size': '140px 140px',
        animation: 'pattern-drift 12s linear infinite',
      }}
    >
      <div class="relative mx-auto max-w-7xl px-6 lg:px-20 py-24 lg:py-28">
        <div ref={reveal} class="reveal-stagger reveal">
          <div>
            <span class="inline-block bg-confetti-pink text-smoke-black font-marker text-sm px-4 py-1.5 rounded-full border-2 border-smoke-black tracking-widest">
              The Full Lineup
            </span>
          </div>
          <h1 class="mt-5 font-display text-5xl sm:text-6xl lg:text-8xl text-molten-coral leading-[1.0] max-w-3xl">
            Every Sauce Has a Story
          </h1>
          <p class="mt-5 font-body text-lg lg:text-xl font-semibold text-smoke-black max-w-xl">
            Small batches. Big personalities. Zero filler. Here's the whole crew.
          </p>
        </div>
      </div>
    </section>
  );
}

function SauceCard(props) {
  return (
    <article
      class={`group relative rounded-2xl border-[3px] border-smoke-black ${props.bg} p-7 lg:p-8 hardshadow transition-all duration-200 hover:-translate-y-1.5 hover:[box-shadow:10px_10px_0_0_#1A1209] flex flex-col`}
    >
      <div class="absolute top-5 right-5 text-2xl">{props.heatEmoji}</div>
      <h3 class={`font-display text-3xl lg:text-4xl ${props.titleColor}`}>{props.title}</h3>
      <p class={`mt-3 font-body text-base ${props.descColor}`}>{props.description}</p>
      <hr class="my-5 border-t-2 border-smoke-black/40" />
      <div class="flex flex-wrap gap-2">
        <span class={`inline-flex items-center font-marker text-xs px-3 py-1 rounded-full border-2 border-smoke-black tracking-widest ${props.pillBg} ${props.pillText}`}>
          Heat: {props.heat}
        </span>
        <span class={`inline-flex items-center font-marker text-xs px-3 py-1 rounded-full border-2 border-smoke-black tracking-widest ${props.pillBg} ${props.pillText}`}>
          {props.base}
        </span>
        <span class={`inline-flex items-center font-marker text-xs px-3 py-1 rounded-full border-2 border-smoke-black tracking-widest ${props.pillBg} ${props.pillText}`}>
          Best on: {props.bestOn}
        </span>
      </div>
    </article>
  );
}

function ProductGrid() {
