function FlameAtNode(props) {
  // floating illustrated flame
  return (
    <div
      class={`flame-pop absolute top-1/2 ${props.class || ''}`}
      style={{ left: `${props.left}%`, 'transition-delay': `${props.delay}ms` }}
    >
      <FlameIcon color={props.color || '#FFD600'} inner="#FFF5E1" size={56} />
    </div>
  );
}

function HeatComparison() {
  const reveal = useReveal();
  const [barRef, setBarRef] = createSignal();
  const [flamesVisible, setFlamesVisible] = createSignal(false);

  onMount(() => {
    const trigger = () => {
      const bar = document.getElementById('flame-bar');
      if (bar) bar.classList.add('is-visible');
      setTimeout(() => {
        document
          .querySelectorAll('#products-section-3 .flame-pop')
          .forEach((el) => el.classList.add('is-visible'));
      }, 200);
    };
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          observer.disconnect();
          trigger();
        }
      },
      { threshold: 0.15 }
    );
    const el = document.getElementById('products-section-3');
    if (el) observer.observe(el);
    setTimeout(trigger, 2400);
  });

  const tiers = [
    { label: '🔥 Mild', desc: 'Flavor-forward, gentle warmth. Perfect for everyday use and heat newcomers.', color: 'text-jalapeno-teal', sauce: 'Serrano Verde' },
    { label: '🔥🔥 Medium', desc: 'Noticeable heat that builds slowly. Great for those who want more than a whisper.', color: 'text-molten-coral', sauce: 'Smoky Diablo' },
    { label: '🔥🔥🔥 Hot', desc: 'A genuine burn with serious flavor complexity. The sweet spot for most heat lovers.', color: 'text-jalapeno-teal', sauce: 'Mango Inferno, Pineapple Fury' },
    { label: '🔥🔥🔥🔥🔥 Extra Hot', desc: 'For experienced palates only. Intense, layered, and deeply satisfying if you can handle it.', color: 'text-molten-coral', sauce: 'Ghost Town' },
    { label: '🔥🔥🔥🔥🔥+ Extreme', desc: "You've been warned. This is the frontier. Bring water. Bring a friend.", color: 'text-ghost-purple', sauce: "Carolina Reaper's Edge" },
  ];

  return (
    <section
      id="products-section-3"
      data-section-type="comparison"
      class="relative bg-lava-cream py-20 lg:py-24"
    >
      <div class="mx-auto max-w-7xl px-6 lg:px-10">
        <div ref={reveal} class="reveal inline-block">
          <span class="inline-block bg-habanero-yellow text-ghost-purple font-marker text-sm px-4 py-1.5 rounded-full border-2 border-smoke-black tracking-widest">
            Heat Guide
          </span>
        </div>
        <h2 ref={reveal} class="reveal mt-4 font-display text-5xl lg:text-6xl text-smoke-black">
          Not Sure Where to Start?
        </h2>
        <p ref={reveal} class="reveal mt-3 font-body text-lg font-semibold text-smoke-black max-w-2xl">
          Here's how our sauces stack up on the Lava Mouth Heat Scale.
        </p>

        <div class="mt-12 grid gap-10 lg:grid-cols-[28%_1fr]">
          <div ref={reveal} class="reveal-stagger reveal space-y-6">
            {tiers.map((t) => (
              <div class="group">
                <h3 class={`font-display text-2xl lg:text-3xl ${t.color} group-hover:translate-x-1 transition-transform border-l-4 border-transparent group-hover:border-habanero-yellow pl-3`}>
                  {t.label}
                </h3>
                <p class="mt-1 font-body text-sm text-smoke-black pl-3">{t.desc}</p>
                <p class="mt-1 font-marker text-xs text-sauce-green pl-3 tracking-widest">{t.sauce}</p>
              </div>
            ))}
          </div>

          <div ref={reveal} class="reveal relative">
            <div class="relative">
              {/* Bar */}
              <div class="relative w-full border-[3px] border-smoke-black rounded-lg overflow-hidden hardshadow-lg h-24">
                <div
                  id="flame-bar"
                  class="bar-grow h-full"
                  style={{
                    background: 'linear-gradient(90deg, #FFD600 0%, #FF4D38 55%, #2A0000 100%)',
                  }}
                />
              </div>
              {/* Flames + labels */}
              <FlameAtNode left={10} delay={200} color="#FFF5E1" />
              <FlameAtNode left={30} delay={500} color="#FFD600" />
              <FlameAtNode left={50} delay={800} color="#FFF5E1" />
              <FlameAtNode left={72} delay={1100} color="#FFD600" />
              <FlameAtNode left={92} delay={1400} color="#FFF5E1" />
              {/* Sauce annotations under bar */}
              <div class="relative mt-6 h-12">
                {[
                  { left: 10, label: 'Serrano Verde', rotate: -5 },
                  { left: 30, label: 'Smoky Diablo', rotate: 5 },
                  { left: 50, label: 'Mango Inferno', rotate: -3 },
                  { left: 72, label: 'Ghost Town', rotate: 4 },
                  { left: 92, label: "Reaper's Edge", rotate: -6 },
                ].map((m) => (
                  <span
                    class="absolute font-marker text-xs lg:text-sm text-smoke-black -translate-x-1/2 whitespace-nowrap"
                    style={{ left: `${m.left}%`, transform: `translateX(-50%) rotate(${m.rotate}deg)` }}
                  >
                    {m.label}
                  </span>
                ))}
              </div>
            </div>
            <p class="mt-10 max-w-2xl font-body text-base text-smoke-black leading-relaxed">
              We rate our sauces on a five-flame scale that balances heat intensity with flavor complexity.
              A five-flame sauce isn't just hot — it's hot AND interesting. Use this guide to find your
              entry point, then work your way up.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

function Testimonials() {
  const reveal = useReveal();
  const items = [
    { name: 'Priya K., Austin TX', body: 'Mango Inferno changed my entire relationship with hot sauce. I put it on my eggs every single morning. My roommates have started hiding it from me.', sauce: 'Mango Inferno' },
    { name: 'Marcus D., Brooklyn NY', body: "Ghost Town is the real deal. Complex, smoky, and absolutely ferocious. I've been a hot sauce nerd for 15 years and this is one of the best I've had.", sauce: 'Ghost Town', featured: true },
    { name: 'Jess T., Portland OR', body: "I bought Serrano Verde as a 'starter' sauce and now I've tried the whole lineup. Send help. Also send more Smoky Diablo.", sauce: 'Serrano Verde → Full Lineup' },
  ];
  return (
    <section
      id="products-section-4"
      data-section-type="testimonial"
      class="relative bg-ghost-purple py-20 lg:py-24 overflow-hidden"
    >
      <Squiggle color="#FF85A1" width={8} class="absolute top-8 -left-8 w-72 opacity-80" />
