      <Triangle color="#FF4D38" class="absolute bottom-10 left-1/3 w-10 opacity-90" />

      <div class="relative mx-auto max-w-7xl px-6 lg:px-10 text-center">
        <div ref={reveal} class="reveal inline-block">
          <span class="inline-block bg-molten-coral text-habanero-yellow font-marker text-sm px-4 py-1.5 rounded-full border-2 border-smoke-black tracking-widest">
            The People Have Spoken
          </span>
        </div>
        <h2 ref={reveal} class="reveal mt-4 font-display text-5xl lg:text-6xl text-lava-cream">
          Hot Takes From Real Mouths
        </h2>
        <div ref={reveal} class="reveal-stagger reveal mt-12 grid gap-6 md:grid-cols-3 items-start text-left">
          {items.map((t, i) => (
            <div
              class={`relative rounded-2xl p-8 transition-all duration-200 hover:bg-lava-cream/15 ${t.featured ? 'lg:-translate-y-6 bg-lava-cream/10 border-2 border-lava-cream/30' : 'bg-lava-cream/5 border-2 border-lava-cream/15'}`}
            >
              <span class="font-display text-7xl text-habanero-yellow leading-none block -mt-2">"</span>
              <p class={`font-body ${t.featured ? 'text-lg' : 'text-base'} text-lava-cream leading-relaxed`}>
                {t.body}
              </p>
              <div class="mt-5">
                <p class="font-marker text-sm tracking-widest text-habanero-yellow">{t.name}</p>
                <p class="mt-1 font-body text-xs text-confetti-pink">Sauce: {t.sauce}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

function ClosingCTA() {
  const reveal = useReveal();
  return (
    <section
      id="products-section-5"
      data-section-type="cta"
      class="relative bg-habanero-yellow py-20 lg:py-24 overflow-hidden border-t-2 border-smoke-black"
    >
      <Diamond color="#7B2FBE" class="absolute -top-6 left-12 w-16 confetti-float-1 rotate-12" />
      <Zigzag color="#7B2FBE" class="absolute -top-3 left-1/3 w-32 confetti-float-2" />
      <Dot color="#7B2FBE" class="absolute -top-4 right-1/3 w-14 confetti-float-3" />
      <Triangle color="#00B8A0" class="absolute -bottom-6 right-12 w-14 confetti-float-4 -rotate-12" />
      <Diamond color="#00B8A0" class="absolute -bottom-4 left-16 w-12 confetti-float-5" />

      <div class="relative mx-auto max-w-7xl px-6 lg:px-10">
        <div ref={reveal} class="reveal-stagger reveal max-w-3xl">
          <div>
            <span class="inline-block bg-molten-coral text-ghost-purple font-marker text-sm px-4 py-1.5 rounded-full border-2 border-smoke-black tracking-widest">
              Ready to Commit?
            </span>
          </div>
          <h2 class="mt-5 font-display uppercase text-smoke-black text-5xl sm:text-6xl lg:text-7xl leading-[0.95]">
            Your Kitchen <br /> Needs This
          </h2>
          <p class="mt-5 max-w-md font-body text-lg font-semibold text-smoke-black">
            Find Lava Mouth at a store near you or ask your favorite local shop to carry us.
          </p>
          <div class="mt-8 flex flex-wrap gap-4">
            <a
              href="/stockists.html"
              class="inline-flex items-center gap-2 bg-molten-coral text-lava-cream font-display text-lg uppercase px-7 py-4 border-[3px] border-smoke-black rounded-md hardshadow hover:-translate-y-1 transition-all"
            >
              Find a Stockist →
            </a>
            <a
              href="/contact.html"
              class="inline-flex items-center gap-2 bg-smoke-black text-lava-cream font-display text-lg uppercase px-7 py-4 border-[3px] border-smoke-black rounded-md hardshadow hover:bg-lava-cream hover:text-smoke-black hover:-translate-y-1 transition-all"
            >
              Contact Us
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}

function ProductsPage() {
  return (
    <PageLayout slug="products">
      <PageHeader />
      <ProductGrid />
      <Marquee
        items={['Mild', 'Medium', 'Hot', 'Extra Hot', 'Extreme', 'Mild', 'Medium', 'Hot']}
      />
      <HeatComparison />
      <Testimonials />
      <ClosingCTA />
    </PageLayout>
  );
}

render(() => <ProductsPage />, document.getElementById('root'));

